class CategoryScore:
    category: str
    score: float

@dataclass
class OverallDecision:
    decision: str
    reason: Optional[str] = None

@dataclass
class ModerationResponse:
    scores: List[CategoryScore]
    overall_decision: OverallDecision
    id: Optional[str] = None

