import os
import requests
import json

class TextSafetyClient:
    def __init__(self, api_key=None, api_endpoint=None):
        self.api_key = api_key or os.getenv("TEXT_SAFETY_API_KEY")
        self.api_endpoint = api_endpoint or os.getenv("TEXT_SAFETY_API_ENDPOINT", "https://api.textsafety.example.com/v1/moderate")

        if not self.api_key:
            raise ValueError("API Key not provided and TEXT_SAFETY_API_KEY environment variable not set.")
        if not self.api_endpoint:
            raise ValueError("API Endpoint not provided and TEXT_SAFETY_API_ENDPOINT environment variable not set.")

    def moderate_text(self, text: str):
        headers = {
            "Content-Type": "application/json",
            "Authorization": f"Bearer {self.api_key}"
        }
        payload = {
            "text": text
        }
        try:
            response = requests.post(self.api_endpoint, headers=headers, json=payload)
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            print(f"Error during text moderation: {e}")
            return {"error": str(e)}

    def batch_moderate_text(self, texts: list[str]):
        headers = {
            "Content-Type": "application/json",
            "Authorization": f"Bearer {self.api_key}"
        }
        payload = {
            "texts": texts
        }
        try:
            response = requests.post(f"{self.api_endpoint}/batch", headers=headers, json=payload)
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            print(f"Error during batch text moderation: {e}")
            return {"error": str(e)}

import os
from typing import List, Dict, Any

from google.cloud import language_v1

def moderate_batch(texts: List[str]) -> List[Dict[str, Any]]:
    client = language_v1.LanguageServiceClient()
    document_type = language_v1.Document.Type.PLAIN_TEXT

    decisions = []
    for text in texts:
        document = {"content": text, "type_": document_type}
        try:
            response = client.moderate_text(document=document)

            moderated = False
            reasons = []
            scores = {}

            for category in response.moderation_categories:
                scores[category.name] = category.score
                if category.score > 0.7:  # Example threshold
                    moderated = True
                    reasons.append(f"Category '{category.name}' scored high: {category.score}")

            decisions.append({
                "text": text,
                "moderated": moderated,
                "reasons": reasons,
                "scores": scores
            })
        except Exception as e:
            decisions.append({"text": text, "moderated": True, "reasons": [f"Error during moderation: {str(e)}"]})

    return decisions
